def fare(km, vehicle='standard', airport=False):
    """Stejný výpočet jako tarif na živém webu (rb_taxi_route_fare)."""
    if vehicle == 'van':
        rate = VAN_AIRPORT if airport else (VAN_LONG if km > LONG_THRESHOLD else VAN_SHORT)
        return int(round(km * rate + BOARDING))
    rate = RATE_AIRPORT if airport else (RATE_LONG if km > LONG_THRESHOLD else RATE_SHORT)
    return int(round(max(MIN_FARE, km * rate + BOARDING)))

def czk(n):
    return f'{n:,}'.replace(',', ' ') + ' Kč'

def km_label(km):
    return f'{km:.2f}'.replace('.', ',') + ' km'

def min_label(m):
    m = int(round(m))
    return f'cca {m//60} h {m%60} min' if m >= 60 else f'cca {m} min'

def route_table(rows):
    """Cenová tabulka ve stejném členění jako na taxihodonin.com."""
    body = ''.join(
        f'<tr><td>{lab}</td><td>{km_label(km)}</td><td>{min_label(mi)}</td>'
        f'<td>{czk(fare(km,"standard",air))}</td><td>{czk(fare(km,"van",air))}</td></tr>'
        for km, mi, air, _g, lab in rows)
    return ('<div class="table-wrap"><table><thead><tr><th>Cíl</th><th>Nejkratší trasa</th>'
            '<th>Přibližný čas</th><th>Osobní vůz<small>1–4 osoby</small></th>'
            f'<th>Větší vůz<small>5–8 osob</small></th></tr></thead><tbody>{body}</tbody></table></div>')

