def icon(name, cls=''):
    return f'<span class="icon {cls}">{ICONS.get(name, ICONS["star"])}</span>'

def rel(depth, target=''):
    prefix = '../' if depth else ''
    if not target:
        return prefix or './'
    if target.startswith('http') or target.startswith('tel:') or target.startswith('mailto:') or target.startswith('#'):
        return target
    if target.startswith('assets/') or '.' in target.rsplit('/', 1)[-1]:
        return f'{prefix}{target}'
    if '#' in target:
        slug, anchor = target.split('#',1)
        return f'{prefix}{slug}/#{anchor}'
    return f'{prefix}{target}/'

