def calc_card():
    """Kalkulačka: volba vozu + ověřené trasy s předpočítanou cenou.

    Volné zadání adres jako na taxihodonin.com by vyžadovalo backend
    (geokódování + routování), proto tu zůstává zadání vzdálenosti a
    sada ověřených tras, u kterých je cena spočítaná při buildu.
    """
    def chips(group):
        out=''
        for km,mi,air,g,lab in ROUTES:
            if g!=group: continue
            out+=(f'<button type="button" data-km="{km}" data-airport="{1 if air else 0}">'
                  f'<span>{lab}</span><small data-std="{fare(km,"standard",air)}" '
                  f'data-van="{fare(km,"van",air)}">{czk(fare(km,"standard",air))}</small></button>')
        return out
    local=chips('primary')+chips('secondary')
    return f'''<div class="calc-card" id="kalkulacka" data-calculator>
<fieldset class="calc-vehicle"><legend>Kolik vás pojede?</legend><div class="calc-vehicle-opts">
<label><input type="radio" name="calc-vehicle" value="standard" checked data-vehicle><span><strong>1–4 osoby</strong><small>osobní vůz</small></span></label>
<label><input type="radio" name="calc-vehicle" value="van" data-vehicle><span><strong>5–8 osob</strong><small>větší vůz</small></span></label></div></fieldset>
<label>Vzdálenost trasy <span>km</span><input type="number" min="1" max="500" step="0.1" value="5" data-distance></label>
<button class="btn btn-gold" type="button" data-calc>{icon('star')} Spočítat cenu</button>
<div class="calc-result"><small>Orientační cena</small><strong data-price>{czk(fare(5))}</strong><span data-rate>Sazba {RATE_SHORT} Kč/km + nástup {BOARDING} Kč · minimum {MIN_FARE} Kč</span></div>
<div class="calc-quick"><strong>Ceny z centra Hodonína</strong><small>Jednosměrná jízda podle zvoleného vozu. Kliknutím trasu načtete.</small><div class="calc-quick-grid">{local}</div></div>
<div class="calc-quick"><strong>Letiště</strong><small>Letištní tarif {RATE_AIRPORT} Kč/km, větší vůz {VAN_AIRPORT} Kč/km.</small><div class="calc-quick-grid">{chips('airport')}</div></div>
</div>'''

