service_listing=''.join(f'<a class="service-card" href="../{slug}/">{icon(ic)}<div><h3>{name}</h3><p>{desc}</p></div>{icon("arrow","arrow")}</a>' for name,slug,ic,desc in SERVICES)
faq_pricing=[('Je cena z kalkulačky závazná?','Kalkulace platí pro přesně zadanou trasu a běžný průběh jízdy. Pokud zákazník změní trasu, přidá mezizastávku nebo vznikne čekání, cena se může upravit podle skutečné jízdy.'),('Kolik stojí nástup?','Základní nástupní sazba je 20 Kč. Aktuální cenu konkrétní jízdy doporučujeme ověřit v kalkulačce, online objednávce nebo u dispečinku.'),('Kolik je minimální jízdné?','Minimální jízdné je 100 Kč. U velmi krátkých jízd se proto může uplatnit minimální částka.'),('Lze cenu ověřit předem?','Ano. U běžné trasy pomůže kalkulačka nebo aplikace. U letiště, firemní jízdy, Drink & Drive, většího vozu a speciálních požadavků doporučujeme potvrzení přes dispečink.'),('Berete kartu?','Platba je možná hotově i kartou. Online platba, Apple Pay nebo Google Pay se řídí zvoleným způsobem objednávky.')]
pricing_examples=[('Krátká jízda po Hodoníně','Centrum, nádraží, nemocnice, poliklinika, úřady, práce, návštěva nebo večerní návrat domů. Pro nejrychlejší řešení volejte dispečink nebo použijte aplikaci.'),('Hodonín a okolní obce','Dubňany, Rohatec, Lužice, Ratíškovice, Mutěnice, Kyjov, Holíč, Skalica a další obce podle aktuální dostupnosti vozů.'),('Letiště a delší trasy','Vídeň-Schwechat, Bratislava, Brno, Praha a další plánované transfery. Doporučujeme objednávku s předstihem a uvedení času letu, počtu osob a zavazadel.'),('Firemní a pravidelné jízdy','Přeprava zaměstnanců, klientů, partnerů a hostů. Po domluvě lze řešit fakturaci, kontaktní osobu a pravidla objednávání.')]
pricing_services=[('Klasické taxi Hodonín','Pro běžné jízdy po městě, na nádraží, do práce, k lékaři, na návštěvu, na nákup nebo z večerní akce. Uveďte přesnou adresu nástupu a cíle, aby šla cena spočítat co nejpřesněji.'),('Letištní transfery','Plánované cesty na letiště Vídeň-Schwechat, Bratislava, Brno-Tuřany a Praha. U letišť doporučujeme objednávku s předstihem a uvedení času odletu/příletu, terminálu, počtu osob a zavazadel.'),('Firemní taxi','Přeprava zaměstnanců, klientů a obchodních partnerů. Po domluvě lze řešit pravidelné trasy, firemní kontaktní osobu, specifický režim objednávek a fakturaci.'),('Senior taxi','Klidná přeprava seniorů k lékaři, na úřad, na nákup nebo návštěvu. Při objednávce sdělte, zda je potřeba více času, pomoc s nástupem nebo prostor pro tašky.'),('Drink & Drive','Odvoz zákazníka i jeho auta domů po předchozí domluvě. Služba vyžaduje koordinaci řidičů, proto je důležité objednat ji s předstihem.'),('VIP přeprava','Reprezentativní přeprava pro obchodní jednání, partnery, hotely, svatby nebo důležité cesty. Dostupnost konkrétního vozu a režimu je potřeba ověřit předem.'),('Kurýrní přeprava','Doručení dokumentů, menších zásilek nebo urgentních předávek v regionu. Při objednávce uveďte velikost zásilky, adresy, kontakty a časové požadavky.')]
