# Právní texty převzaté z taxihodonin.com (viz LEGAL_CONTENT výše).
def legal_body_html(blocks):
    out=''
    for tag,val in blocks:
        if tag=='ul':
            out+='<ul>'+''.join(f'<li>{v}</li>' for v in val)+'</ul>'
        elif tag=='h2':
            out+=f'<h2>{val}</h2>'
        elif tag=='h3':
            out+=f'<h3>{val}</h3>'
        else:
            out+=f'<p>{val}</p>'
    return out

for slug,data in LEGAL_CONTENT.items():
    blocks=data['blocks']
    # První H2 je nadpis stránky, ten už nese hero.
    heading=data['h1']
    # První H2 opakuje nadpis stránky, ten už nese hero.
    rest=blocks[1:] if blocks and blocks[0][0]=='h2' else blocks
    lead=next((v for t,v in rest if t=='p'), '')
    rest=[(t,v) for t,v in rest if not (t=='p' and v==lead)]
    body=(f'<section class="inner-hero"><div class="container inner-hero-grid"><div>'
          f'<span class="eyebrow">Právní informace</span><h1>{heading}</h1><p>{lead}</p>'
          f'</div></div></section><section class="section"><div class="container narrow prose legal">'
          f'{legal_body_html(rest)}</div></section>')
    pages[slug]=page_shell(data['title'],data['desc'],body,slug)

